import { CommonModule, isPlatformBrowser } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  Inject,
  OnInit,
  PLATFORM_ID,
} from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { PaymentsService } from '../../core/services/payments.service';
import { Location } from '@angular/common';
import { LucideAngularModule } from 'lucide-angular';
import { TranslationService } from '../../core/services/translation.service';

@Component({
	selector: 'app-unsubscription',
	standalone: true,
	imports: [CommonModule, LucideAngularModule],
	templateUrl: './unsubscription.component.html',
	styleUrl: './unsubscription.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UnsubscriptionComponent implements OnInit {
	subscriber_id: any;
  type: any;
  success = false;
  private readonly isBrowser: boolean;

  async showAlert(options: any) {
    const Swal = (await import('sweetalert2')).default;
    return Swal.fire(options);
  }

  constructor(
    public translationService: TranslationService,
    public route: ActivatedRoute,
    public router: Router,
    public paymentservice: PaymentsService,
    public location: Location,
    @Inject(PLATFORM_ID) platformId: object
  ) {
    this.isBrowser = isPlatformBrowser(platformId);
    this.subscriber_id = this.route.snapshot.paramMap.get('subscriberID');
  }

  ngOnInit(): void {
    if (!this.isBrowser) {
      return;
    }

    const currentLocation = this.location.path();

    if (this.subscriber_id && currentLocation.includes('cancel')) {
      this.type = 'cancel';
      this.cancelSubscription();
    } else if (this.subscriber_id && currentLocation.includes('pause')) {
      this.type = 'pause';
      this.showAlert({
        title: "Are you sure?",
        text: "You want be Pause from Pixtar Service!",
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: "#878787",
        cancelButtonColor: "#d33",
        confirmButtonText: "Yes, Pause!"
      }).then((result) => {
        if (result.isConfirmed) {
          this.pauseSubscription();
        }
      });
    } else if (this.subscriber_id && currentLocation.includes('resume')) {
      this.type = 'resume';
      this.showAlert({
        title: "Are you sure?",
        text: "You want be Resume Pixtar Service!",
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: "#878787",
        cancelButtonColor: "#d33",
        confirmButtonText: "Yes, Resume!"
      }).then((result) => {
        if (result.isConfirmed) {
          this.resumeSubscription();
        }
      });
    }
  }

  async cancelSubscription() {
    const obj: Record<string, unknown> = {};
    let reason_obj = {};
    const { value: reason } = await this.showAlert({
      title: "You want be Unsubscribe from Pixtar Service!",
      text: "Select reason for why are you cancelling,",
      input: "select",
      confirmButtonColor: "#878787",
      inputOptions: {
        customer_service: "Customer service was less than expected",
        low_quality: "Quality was less than expected",
        missing_features: "Some features are missing",
        other: "Other reason",
        switched_service: "I’m switching to a different service",
        too_complex: "Ease of use was less than expected",
        too_expensive: "It’s too expensive",
        unused: "I don’t use the service enough",
      },
      inputPlaceholder: "Select a Reason",
      // showCancelButton: true,
      inputValidator: (value: string) => {
        return new Promise<void | string>((resolve) => {
          if (value) {
            resolve(); // ✅ now valid
          } else {
            resolve("You need to select reason :)");
          }
        });
      }
    });
    if (reason) {
      reason_obj = reason;
    }
    if (this.subscriber_id && reason) {
      obj['subscriptionId'] = this.subscriber_id;
      obj['reason_obj'] = reason_obj;
      this.paymentservice.stripeSubscribeCancel(obj).subscribe(
        (response) => {
          if (response.body.code == 200) {
            this.success = true;
            this.showAlert({
              title: "Cancelled!",
              text: "Your Subscription has been Cancelled.",
              icon: "success",
              confirmButtonColor: "#878787",
            });
            // setTimeout(()=>{
            //   Swal.close()	
            //   this.router.navigate(['/']);
            // },5000);
          } else {
            this.showAlert({
              title: "Error!",
              text: "Somethiing Error to Cancel your Subscription.",
              icon: "warning",
              confirmButtonColor: "#878787",
            });
          }
        },
      );
    }
  }

  pauseSubscription() {
    if (this.subscriber_id) {
      const obj: Record<string, unknown> = {};
      obj['subscriptionId'] = this.subscriber_id;
      this.paymentservice.stripeSubscribePause(obj).subscribe(
        (response) => {
          if (response.body.code == 200) {
            this.success = true;
            this.showAlert({
              title: "Pause!",
              text: "Your Subscription has been Paused.",
              icon: "success",
              confirmButtonColor: "#878787",
            });
            // setTimeout(()=>{
            //   Swal.close()	
            //   this.router.navigate(['/']);
            // },5000);
          } else {
            this.showAlert({
              title: "Error!",
              text: "Somethiing Error to Pause your Subscription.",
              icon: "warning",
              confirmButtonColor: "#878787",
            });
          }
        },
      );
    }
  }

  resumeSubscription() {
    if (this.subscriber_id) {
      const obj: Record<string, unknown> = {};
      obj['subscriptionId'] = this.subscriber_id;
      this.paymentservice.stripeSubscribeResume(obj).subscribe(
        (response) => {
          if (response.body.code == 200) {
            this.success = true;
            this.showAlert({
              title: "Resume!",
              text: "Your Subscription has been Resume.",
              icon: "success",
              confirmButtonColor: "#878787",
            });
          } else {
            this.showAlert({
              title: "Error!",
              text: "Somethiing Error to Resume your Subscription.",
              icon: "warning",
              confirmButtonColor: "#878787",
            });
          }
        },
      );
    }
  }
}
